SELECT 
    (SELECT COUNT(*) FROM client WHERE gender = 'M' AND district_id = (
        SELECT district_id FROM district WHERE A2 = 'South Bohemia' ORDER BY A11 DESC LIMIT 1
    )) * 100.0 / 
    (SELECT COUNT(*) FROM client WHERE district_id = (
        SELECT district_id FROM district WHERE A2 = 'South Bohemia' ORDER BY A11 DESC LIMIT 1
    )) AS percentage_male_clients;

