SELECT COUNT(*) FROM molecule WHERE molecule_id IN (
  SELECT molecule_id FROM atom WHERE element = 'C' OR element = 'N' OR element = 'O' OR element = 'S' OR element = 'P' OR element = 'Cl' OR element = 'Br' OR element = 'I'
) LIMIT 100;

SELECT bond_type FROM bond WHERE molecule_id IN (
  SELECT molecule_id FROM atom WHERE atom_id IN ('TR004_8', 'TR004_20')
) AND atom_id IN ('TR004_8', 'TR004_20');

SELECT SUM(CASE WHEN T2.label LIKE '%carcinogenic%' THEN 1 ELSE 0 END) - SUM(CASE WHEN T2.label NOT LIKE '%carcinogenic%' THEN 1 ELSE 0 END) AS difference
FROM connected AS T1
JOIN molecule AS T2 ON T1.molecule_id = T2.molecule_id;

SELECT element
FROM atom
WHERE atom_id NOT IN (
  SELECT atom_id
  FROM connected
);

SELECT CAST(SUM(CASE WHEN bond_type = 'single' THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(*) AS percentage
FROM bond
WHERE bond_type IN ('single', 'double', 'triple');

SELECT COUNT(*) 
FROM molecule 
WHERE molecule_id BETWEEN 'TR000' AND 'TR030';

SELECT CASE WHEN EXISTS (
  SELECT 1
  FROM molecule m
  JOIN bond b ON m.molecule_id = b.molecule_id
  WHERE m.label = 'TR000' AND b.bond_type = 'carcinogenic'
) THEN 'Carcinogenic' ELSE 'Not Carcinogenic' END AS carcinogenic_status;

